168 |      *
169 |      * @param schema - Zod schema
170 |      * @returns JSON Schema 对象
171 |      */
172 |     private static zodToJsonSchema(schema: any): Record<string, unknown> {
173 |         // 基础实现，处理常见类型
174 |         if (schema._def?.typeName === 'ZodObject') {
175 |             const shape = schema._def.shape();
176 |             const properties: Record<string, unknown> = {};
177 |             const required: string[] = [];
178 | 
179 |             for (const [key, value] of Object.entries(shape)) {
180 |                 const def = (value as any)._def;
181 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
182 | 
183 |                 // 检查是否是可选字段
184 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
185 |                                    (value as any).isOptional?.();
186 |                 if (!isOptional) {
187 |                     required.push(key);
188 |                 }
189 |             }
190 | 
191 |             return {
192 |                 type: 'object',
193 |                 properties,
194 |                 required: required.length > 0 ? required : undefined,
195 |                 additionalProperties: false,
196 |             };
197 |         }
198 | 
199 |         return { type: 'object', properties: {}, additionalProperties: false };
200 |     }
201 | 
202 |     /**
203 |      * 将 Zod 类型转换为 JSON Schema 类型
204 |      *
205 |      * @param def - Zod 类型定义
206 |      * @param key - 字段名（用于错误信息）
207 |      * @returns JSON Schema 类型定义
208 |      */
209 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
210 |         const typeName = def?.typeName;
211 | 
212 |         switch (typeName) {
213 |             case 'ZodString':
214 |                 return { type: 'string' };
215 | 
216 |             case 'ZodNumber':
217 |                 return { type: 'number' };
218 | 
219 |             case 'ZodBoolean':
220 |                 return { type: 'boolean' };
221 | 
222 |             case 'ZodNull':
223 |                 return { type: 'null' };
224 | 
225 |             case 'ZodArray':
226 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
227 |                 return {
228 |                     type: 'array',
229 |                     items: itemType,
230 |                 };
231 | 
232 |             case 'ZodObject':
233 |                 return this.zodToJsonSchema({ _def: def });
234 | 
235 |             case 'ZodOptional':
236 |             case 'ZodNullable':
237 |             case 'ZodDefault':
238 |                 // innerType 是 Zod 对象，需要获取其 _def
239 |                 return this.zodTypeToJsonSchema(def.innerType._def, key);
240 | 
241 |             case 'ZodEnum':
242 |                 return {
243 |                     type: 'string',
244 |                     enum: def.values,
245 |                 };
246 | 
247 |             case 'ZodLiteral':
248 |                 return {
249 |                     type: typeof def.value,
250 |                     const: def.value,
251 |                 };
252 | 
253 |             case 'ZodUnion':
254 |             case 'ZodDiscriminatedUnion':
255 |                 return {
256 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
257 |                 };
258 | 
259 |             case 'ZodEffects':
260 |                 // 处理带描述的字段
261 |                 const innerSchema = this.zodTypeToJsonSchema(def.innerType._def, key);
262 |                 if (def.description) {
263 |                     return { ...innerSchema, description: def.description };
264 |                 }
265 |                 return innerSchema;
266 | 
267 |             default:
268 |                 // 未知类型，使用 any
269 |                 if (typeName !== undefined) {
270 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
271 |                 } else {
272 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
273 |                 }
274 |                 return {};
275 |         }
276 |     }
277 | }
